engine.kernelCheckParse:
function kernelCheckParse(raw) {
  // Returns null when the payload can't be trusted. A half-written marker
  // must not be able to trigger an update notice.
  if (!raw || typeof raw !== "object") return null;
  var v = typeof raw.version === "string" ? raw.version.trim() : "";
  var url = typeof raw.importUrl === "string" ? raw.importUrl.trim() : "";
  if (!v) return null;
  if (!/^https:\/\//i.test(url)) return null;
  return {
    version: v,
    importUrl: url,
    builtAt: typeof raw.builtAt === "string" ? raw.builtAt : "",
    bytes: isFinite(Number(raw.bytes)) ? Number(raw.bytes) : 0,
    notes: typeof raw.notes === "string" ? raw.notes : "",
    // [{name, role}] — who to ask. Entries missing a name are dropped so a
    // half-filled marker can't render an empty bullet.
    adminContacts: Array.isArray(raw.adminContacts)
      ? raw.adminContacts.map(function (c) {
          if (typeof c === "string") return { name: c.trim(), role: "" };
          if (!c || typeof c !== "object") return null;
          return { name: String(c.name || "").trim(), role: String(c.role || "").trim() };
        }).filter(function (c) { return c && c.name; })
      : [],
  };
}

engine.kernelCheckCompare:
function kernelCheckCompare(current, latest) {
  // → { state: "current" | "behind" | "ahead" | "unknown", reason }
  // Only "behind" is actionable. Everything else stays silent: a wrong
  // "you're out of date" costs more trust than a missed one.
  // Sortable key. Builds carry HHMM since 2026-09-12; older ones have only
  // a date, and two of those from the same day cannot be ordered at all —
  // that case has to read as unknown, never as "behind".
  function _stamp(s) {
    var m = /^v3-(\d{4})-(\d{2})-(\d{2})(?:-(\d{4}))?-/.exec(String(s || ""));
    if (!m) return null;
    return { day: m[1] + m[2] + m[3], time: m[4] || null };
  }
  var cur = String(current == null ? "" : current).trim();
  var lat = (latest && latest.version) ? String(latest.version).trim() : "";
  if (!lat) return { state: "unknown", reason: "nothing published" };
  if (!cur) return { state: "unknown", reason: "kernel reports no version" };
  if (cur === lat) return { state: "current", reason: "exact match" };

  var ld = _stamp(lat);
  if (!ld) return { state: "unknown", reason: "published version unparseable" };
  var cd = _stamp(cur);
  // A kernel whose version predates the stamped format is by definition
  // older than anything published under it.
  if (!cd) return { state: "behind", reason: "unstamped kernel" };
  if (cd.day > ld.day) return { state: "ahead", reason: "local build newer than published" };
  if (cd.day < ld.day) return { state: "behind", reason: "older build date" };
  // Same day. With a time on both sides the order is knowable.
  if (cd.time && ld.time) {
    if (cd.time > ld.time) return { state: "ahead", reason: "later build the same day" };
    if (cd.time < ld.time) return { state: "behind", reason: "earlier build the same day" };
    return { state: "unknown", reason: "same timestamp, different hash" };
  }
  // One side has no time, so two same-day builds cannot be ordered.
  // Calling that "behind" told anyone running a NEWER hand-pasted kernel
  // to downgrade, on every single load.
  return { state: "unknown", reason: "same day, order unknowable" };
}

view.renderKernelUpdate:
function renderKernelUpdate(opts) {
  opts = opts || {};
  var latest = opts.latest || {};
  var onLater = typeof opts.onLater === "function" ? opts.onLater : function () {};

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // navigator.clipboard is blocked in some Script Lab iframe contexts, so
  // the textarea path is a real fallback for a known boundary, not a
  // bug-paver. When BOTH fail the URL is left selected and the button says
  // so — never a "Copied!" that didn't happen.
  function copyText(text) {
    function viaTextarea() {
      return new Promise(function (resolve, reject) {
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.style.cssText = "position:fixed;left:-9999px;opacity:0;";
        document.body.appendChild(ta);
        ta.select();
        var ok = false;
        try { ok = document.execCommand("copy"); } catch (_e) { ok = false; }
        document.body.removeChild(ta);
        if (ok) resolve(); else reject(new Error("clipboard blocked"));
      });
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(viaTextarea);
    }
    return viaTextarea();
  }

  var ov = document.createElement("div");
  ov.className = "_eli3_kc_overlay";
  ov.style.cssText =
    "position:fixed; inset:0; z-index:9650;" +
    "background:rgba(8,17,28,0.58);" +
    "display:flex; align-items:center; justify-content:center;" +
    "padding:14px; box-sizing:border-box;" +
    "font-family:Inter, system-ui, sans-serif;";




  // "Andrew Nemiroff (Admin) or Jared Lerner (Assistant to the Admin)".
  // Falls back to the generic phrasing when the marker names nobody.
  var contactsHtml = (function () {
    var list = Array.isArray(latest.adminContacts) ? latest.adminContacts : [];
    if (!list.length) return "your ELI admin";
    var parts = list.map(function (c) {
      return '<b style="color:#334155;">' + esc(c.name) + '</b>' +
        (c.role ? " (" + esc(c.role) + ")" : "");
    });
    if (parts.length === 1) return parts[0];
    return parts.slice(0, -1).join(", ") + " or " + parts[parts.length - 1];
  })();

  var card = document.createElement("div");
  card.className = "_eli3_kc_card";
  card.style.cssText =
    "width:min(460px, 100%); max-height:calc(100vh - 28px);" +
    "display:flex; flex-direction:column; background:#ffffff;" +
    "border:1px solid #c9a227; box-shadow:0 18px 50px rgba(8,17,28,0.4);";

  // Five steps, and the first two ARE the buttons — the instruction and
  // the control that performs it sit together rather than in separate
  // furniture above the list.
  var NUM = "flex:0 0 20px; height:20px; border-radius:50%; background:#c9a227;color:#1a1a1a; display:flex; align-items:center; justify-content:center;font:800 11px/1 Inter,sans-serif;";
  var TXT = "font-size:13px; color:#243141; line-height:1.6;";
  card.innerHTML =
    '<div style="flex:0 0 auto; background:#0f172a; padding:16px;">' +
      '<div style="font:800 15px/1.3 Inter,sans-serif; color:#f2d866;">' +
        '\u2728 There\u2019s a new version of ELI OS!</div>' +
      '<div style="font-size:12px; color:#94a3b8; margin-top:6px;">' +
        'Five steps to update, about a minute.</div>' +
    '</div>' +

    '<div style="flex:1 1 auto; overflow-y:auto; padding:16px;">' +
      // 1 — copy. The link stays visible so you can see what you took.
      '<div style="display:flex; gap:11px; margin-bottom:14px;">' +
        '<div style="' + NUM + '">1</div>' +
        '<div style="flex:1; min-width:0;">' +
          '<div style="' + TXT + ' margin-bottom:7px;"><b>Copy the link.</b> ' +
            'This window closes in step 3.</div>' +
          '<input data-kc-url readonly value="' + esc(latest.importUrl) + '" ' +
            'style="width:100%; box-sizing:border-box; padding:8px 10px; margin-bottom:7px;' +
            'border:1px solid #cbd5e1; background:#f8fafc; color:#0f172a;' +
            'font:600 11px/1.3 ui-monospace,Consolas,monospace; outline:none;">' +
          '<button data-kc-copy style="width:100%; height:32px; cursor:pointer;' +
            'background:#c9a227; border:1px solid #a8871d; color:#1a1a1a;' +
            'font:800 12px/1 Inter,sans-serif;">Copy link</button>' +
        '</div>' +
      '</div>' +

      // 2 — keep the rest somewhere the closing window cannot take away.
      '<div style="display:flex; gap:11px; margin-bottom:18px;">' +
        '<div style="' + NUM + '">2</div>' +
        '<div style="flex:1; min-width:0;">' +
          '<div style="' + TXT + ' margin-bottom:7px;">' +
            '<b>Put the remaining steps in your document</b> so you can still ' +
            'read them.</div>' +
          '<button data-kc-doc style="width:100%; height:32px; cursor:pointer;' +
            'background:#ffffff; border:1px solid #94a3b8; color:#0f172a;' +
            'font:700 12px/1 Inter,sans-serif;">Put steps 3\u20135 in my document</button>' +
        '</div>' +
      '</div>' +

      '<div style="display:flex; gap:11px; margin-bottom:13px;">' +
        '<div style="' + NUM + '">3</div>' +
        '<div style="' + TXT + '"><b>Delete the ELI snippet in Script Lab.</b> ' +
          'Importing on top of it leaves two copies fighting over the taskpane.</div>' +
      '</div>' +
      '<div style="display:flex; gap:11px; margin-bottom:13px;">' +
        '<div style="' + NUM + '">4</div>' +
        '<div style="' + TXT + '">Choose <b>Import</b> and paste the link.</div>' +
      '</div>' +
      '<div style="display:flex; gap:11px;">' +
        '<div style="' + NUM + '">5</div>' +
        '<div style="' + TXT + '">Run it. Your tools, settings and trophies ' +
          'carry over.</div>' +
      '</div>' +
    '</div>' +

    '<div style="flex:0 0 auto; border-top:1px solid #e2e8f0; padding:14px 16px;">' +
      '<div style="font-size:12px; color:#64748b; line-height:1.6;">' +
        'Need help? Contact ' + contactsHtml + '</div>' +
      '<button data-kc-later style="width:100%; height:34px; margin-top:12px;' +
        'cursor:pointer; background:#f8fafc; border:1px solid #cbd5e1; color:#334155;' +
        'font:700 13px/1 Inter,sans-serif;">Close</button>' +
    '</div>';
  ov.appendChild(card);
  document.body.appendChild(ov);

  function close(cb) {
    if (ov.parentNode) ov.parentNode.removeChild(ov);
    cb();
  }

  var urlEl = card.querySelector("[data-kc-url]");
  var copyBtn = card.querySelector("[data-kc-copy]");
  copyBtn.onclick = function () {
    copyText(latest.importUrl).then(function () {
      copyBtn.textContent = "Copied";
      copyBtn.style.background = "#15803d";
      copyBtn.style.color = "#f0fdf4";
      setTimeout(function () {
        copyBtn.textContent = "Copy link";
        copyBtn.style.background = "#c9a227";
        copyBtn.style.color = "#1a1a1a";
      }, 1600);
    }).catch(function () {
      // Say what actually happened and leave the text selected.
      try { urlEl.focus(); urlEl.select(); } catch (_e) {}
      copyBtn.textContent = "Press ⌘/Ctrl+C";
      copyBtn.style.background = "#7f1d1d";
      copyBtn.style.color = "#fee2e2";
    });
  };
  var docBtn = card.querySelector("[data-kc-doc]");
  if (docBtn) {
    docBtn.onclick = function () {
      if (typeof opts.onPutInDoc !== "function") return;
      docBtn.disabled = true;
      docBtn.textContent = "Writing\u2026";
      Promise.resolve(opts.onPutInDoc()).then(function (ok) {
        // Declined at the confirm: restore the button. Written: keep it
        // disabled, or a second click inserts a second copy of the steps.
        var declined = ok === false;
        docBtn.textContent = declined ? "Put steps 3\u20135 in my document" : "Added to your document";
        docBtn.disabled = !declined;
      }).catch(function (err) {
        // Say what failed rather than leaving a dead button.
        docBtn.disabled = false;
        docBtn.textContent = "Couldn\u2019t write \u2014 try Copy link";
        if (typeof showToast === "function") {
          showToast("Couldn't write to the document: " + ((err && err.message) || "unknown"), "err");
        }
      });
    };
  }
  card.querySelector("[data-kc-later]").onclick = function () { close(onLater); };

  return ov;
}

