/* tools/kernel_check/style.css
   Keyframes only — everything else is inlined on the element for
   guaranteed paint (taskpane_v3.css is the only sheet the runtime loads). */

._eli3_kc_overlay { animation: _eli3_kc_fade 160ms ease-out; }
._eli3_kc_card { animation: _eli3_kc_rise 220ms cubic-bezier(.2,.8,.3,1); }

@keyframes _eli3_kc_fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes _eli3_kc_rise {
  from { opacity: 0; transform: translateY(10px) scale(.985); }
  to   { opacity: 1; transform: none; }
}
